pm.test("Validar status HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Validar lista de produtos", function () {
    const resposta = pm.response.json();
    pm.expect(resposta.products).to.be.an("array");
});

pm.test("Validar lista de produtos não vazia", function () {
    const resposta = pm.response.json();    
    pm.expect(resposta.products.length).to.be.above(0);
});

pm.test("Validar ID do primeiro produto", function () {
    const resposta = pm.response.json();
    pm.expect(resposta.products).to.be.an("array").that.is.not.empty;
    const produto = resposta.products[0];

    pm.expect(produto.id).to.be.a("number");
    pm.expect(produto.id).to.be.above(0);
});

pm.test("Validar título do primeiro produto", function () {
    const resposta = pm.response.json();
    
    pm.expect(resposta.products).to.be.an("array").that.is.not.empty;

    const produto = resposta.products[0];

    pm.expect(produto.title).to.be.a("string");
    pm.expect(produto.title.trim()).to.not.be.empty;
});

pm.test("Validar preço do primeiro produto", function () {
    const resposta = pm.response.json();
    
    pm.expect(resposta.products).to.be.an("array").that.is.not.empty;

    const produto = resposta.products[0];

    pm.expect(produto.price).to.be.a("number");
    pm.expect(produto.price).to.be.above(0);
});

pm.test("Validar ID de todos os produtos", function () {
    const resposta = pm.response.json();
    
    pm.expect(resposta.products).to.be.an("array").that.is.not.empty;

    resposta.products.forEach(function (produto) {
        pm.expect(produto.id).to.be.a("number");
        pm.expect(produto.id).to.be.above(0);
    });
});


pm.test("Identificar produtos com preço inválido", function () {
    const resposta = pm.response.json();
   
    pm.expect(resposta.products).to.be.an("array").that.is.not.empty;

    const produtosInvalidos = resposta.products
        .filter(function (produto) {
            return typeof produto.price !== "number" || produto.price <= 0;
        })
        .map(function (produto) {
            return {
                id: produto.id,
                titulo: produto.title,
                preco: produto.price
            };
        });

    console.log(
        "RELATÓRIO DE PRODUTOS COM PREÇO INVÁLIDO:\n" +
        JSON.stringify(produtosInvalidos, null, 2)
    );  

    pm.expect(produtosInvalidos.length).to.equal(0);
});
